INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (72, 'El Cañón del Colca: Abismo de Civilizaciones', 'El Cañón del Colca, uno de los más profundos del mundo con más de 3.400 metros de profundidad, fue habitado por las culturas Collagua y Cabana mucho antes de la llegada de los incas. Sus andenes agrícolas, esculpidos en las laderas hace más de mil años, aún son utilizados por los pobladores locales para el cultivo. La región fue incorporada al Tahuantinsuyo en el siglo XV, cuando el inca Mayta Cápac conquistó estas tierras y aprovechó sus fértiles terrazas para el sustento del imperio.', '1450-01-01', '2024-03-15', false, 'STORY', 'ACTIVE', 1, 72);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (73, 'El Lago Sagrado de los Incas', 'El lago Titicaca, ubicado a 3.812 metros sobre el nivel del mar, es el lago navegable más alto del mundo y fue considerado por los incas como el lugar de origen del dios Viracocha y de los primeros soberanos del Tahuantinsuyo, Manco Cápac y Mama Ocllo. Sus aguas albergan a los Uros, pueblo ancestral que construye sus islas flotantes con totora desde tiempos preincaicos. La conquista española en el siglo XVI transformó la región, aunque las comunidades indígenas preservaron sus tradiciones a lo largo de los siglos.', '0001-01-01', '2024-05-22', false, 'STORY', 'ACTIVE', 2, 73);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (74, 'El Gran Espejo Blanco de Bolivia', 'El Salar de Uyuni, con sus 10.582 kilómetros cuadrados, es el desierto de sal más extenso del planeta, formado hace aproximadamente 40.000 años por la evaporación de antiguos lagos prehistóricos. Las culturas precolombinas de la región, entre ellas los aymara, consideraban estas tierras sagradas y las atravesaban en sus rutas de intercambio de bienes entre el altiplano y los valles. En el siglo XIX, durante las guerras de independencia sudamericanas, el salar sirvió como ruta de desplazamiento de tropas por su vastedad y la escasez de obstáculos naturales.', '0001-01-01', '2024-07-04', false, 'INFORMATION', 'ACTIVE', 3, 74);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (75, 'Las Torres del Fin del Mundo', 'Las Torres del Paine, imponentes monolitos de granito que se elevan casi 2.500 metros sobre la Patagonia chilena, fueron habitadas por los pueblos tehuelche, conocidos como aonikenk, quienes recorrían estas tierras como cazadores-recolectores desde hace miles de años. El explorador europeo John Byron pasó por las costas patagónicas en 1741, y a lo largo del siglo XIX la región comenzó a ser estudiada por naturalistas como Charles Darwin durante su viaje en el Beagle. El área fue declarada Parque Nacional en 1959, consolidando su protección como uno de los paisajes más espectaculares del hemisferio sur.', '1959-05-13', '2024-09-30', false, 'INFORMATION', 'ACTIVE', 4, 75);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (76, 'El Desierto Más Árido de la Tierra', 'El desierto de Atacama, considerado el más árido del planeta no polar, fue habitado por culturas como la atacameña o lickanantay, quienes construyeron pueblos llamados pucaras y desarrollaron sofisticadas redes de irrigación denominadas aqueduct canales o "puquios" para sobrevivir en tan extremas condiciones. Durante la época colonial, la región adquirió importancia estratégica por sus yacimientos de plata, cobre y salitre, siendo este último mineral la causa de la Guerra del Pacífico entre Chile, Bolivia y Perú entre 1879 y 1884. La victoria chilena en ese conflicto le otorgó el control definitivo del territorio y sus riquísimas reservas minerales.', '1879-04-05', '2024-02-18', false, 'STORY', 'ACTIVE', 1, 76);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (77, 'El Misterio de los Moái', 'La Isla de Pascua, conocida por sus habitantes como Rapa Nui, fue colonizada por polinesios alrededor del siglo V d.C., quienes tallaron cerca de 900 estatuas gigantes de piedra volcánica llamadas moái en honor a sus ancestros deificados. La civilización rapanui alcanzó su apogeo entre los siglos XIII y XV, pero sufrió un colapso demográfico y ecológico severo producto de la deforestación masiva y las guerras internas. El navegante holandés Jacob Roggeveen fue el primer europeo en avistar la isla el 5 de abril de 1722, día de Pascua de Resurrección, dándole el nombre con el que es conocida en Occidente.', '1722-04-05', '2024-04-07', false, 'STORY', 'ACTIVE', 2, 77);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (78, 'Los Geoglifos del Desierto Peruano', 'Las Líneas de Nazca son enormes geoglifos trazados en la árida pampa peruana por la cultura nazca entre los años 500 a.C. y 500 d.C., representando figuras zoomorfas, fitomorfas y geométricas que solo pueden apreciarse plenamente desde el aire. Su función exacta permanece debatida entre los investigadores, aunque la hipótesis más extendida sugiere que estaban relacionadas con rituales de culto al agua y a las deidades de la fertilidad, fundamentales para una civilización que habitaba una de las regiones más secas del mundo. La arqueóloga alemana Maria Reiche dedicó más de cuatro décadas de su vida a su estudio y preservación, contribuyendo a que en 1994 fueran declaradas Patrimonio de la Humanidad por la UNESCO.', '0001-01-01', '2024-06-12', false, 'INFORMATION', 'ACTIVE', 3, 78);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (79, 'El Ombligo del Mundo Inca', 'Cusco, cuyo nombre en quechua significa "ombligo del mundo", fue fundada por el mítico Manco Cápac alrededor del siglo XIII y se convirtió en la capital del Tahuantinsuyo, el mayor imperio precolombino de América, que llegó a albergar entre 10 y 12 millones de habitantes. Sus calles estaban trazadas en forma de puma, animal sagrado para los incas, y sus construcciones de piedra encajada sin mortero resistieron terremotos que destruyeron los edificios coloniales españoles superpuestos sobre ellas. En noviembre de 1533, Francisco Pizarro tomó la ciudad tras la captura y ejecución del inca Atahualpa, imponiendo sobre sus templos y palacios las iglesias y mansiones del nuevo orden colonial.', '1533-11-15', '2024-08-05', false, 'STORY', 'ACTIVE', 4, 79);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (80, 'El Laboratorio de la Evolución', 'Las Islas Galápagos, de origen volcánico y situadas a unos 1.000 kilómetros de la costa ecuatoriana, fueron descubiertas accidentalmente en 1535 por el obispo Fray Tomás de Berlanga cuando su nave fue desviada por las corrientes durante un viaje a Perú. Su fauna única, producto de millones de años de evolución en aislamiento, inspiró al naturalista inglés Charles Darwin durante su visita en 1835 a bordo del HMS Beagle, sentando las bases de su teoría de la evolución por selección natural publicada en "El origen de las especies" en 1859. Ecuador anexó formalmente el archipiélago en 1832, y hoy son consideradas uno de los ecosistemas más preciados y frágiles del planeta.', '1835-09-15', '2024-10-20', false, 'STORY', 'ACTIVE', 1, 80);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (81, 'La Carita de Dios: Primera Ciudad Patrimonio de la Humanidad', 'Quito fue fundada por los españoles el 6 de diciembre de 1534 sobre las ruinas de un importante asentamiento inca, en las laderas del volcán Pichincha a 2.850 metros de altitud. Su centro histórico conserva el conjunto urbano colonial mejor preservado de América Latina, con más de 5.000 inmuebles históricos, 40 iglesias y conventos y 16 plazas, que motivaron a la UNESCO a declararlo en 1978 como el primer sitio Patrimonio de la Humanidad junto con Cracovia. El 24 de mayo de 1822, la Batalla de Pichincha librada en las faldas del volcán homónimo selló la independencia ecuatoriana del dominio español.', '1534-12-06', '2024-01-25', false, 'INFORMATION', 'ACTIVE', 2, 81);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (82, 'La Mayor Llanura Inundable del Planeta', 'El Pantanal, con sus aproximadamente 150.000 kilómetros cuadrados que se extienden por Brasil, Bolivia y Paraguay, es el humedal tropical más grande del mundo y alberga una biodiversidad extraordinaria, con más de 1.000 especies de aves, 400 de peces y 300 de mamíferos. Antes de la conquista española y portuguesa, la región fue habitada por numerosos pueblos indígenas como los xarayes, guaicurús y bororos, quienes aprovechaban sus recursos naturales con profundo conocimiento del ciclo de inundaciones estacionales. Las expediciones coloniales portuguesas del siglo XVII exploraron el Pantanal en busca de la legendaria ciudad de El Dorado, encontrando en cambio yacimientos de oro en las serranías circundantes que impulsaron la colonización de Mato Grosso.', '0001-01-01', '2024-11-08', false, 'INFORMATION', 'ACTIVE', 3, 82);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (83, 'La Roma Negra de América', 'Salvador de Bahía fue fundada en 1549 como la primera capital del Brasil colonial y se convirtió en el principal puerto de entrada del tráfico de esclavos africanos en América, con estimaciones que indican que entre 1,5 y 4 millones de africanos desembarcaron en sus muelles a lo largo de tres siglos. Esta brutal historia dio lugar a una de las culturas afrobrasileñas más ricas y resistentes del continente, que se expresa en el candomblé, la capoeira, el carnaval y la gastronomía bahiana, mezcla de tradiciones yoruba, fon y angola con elementos indígenas y europeos. El Pelourinho, su casco histórico de coloridas fachadas barrocas, fue declarado Patrimonio de la Humanidad por la UNESCO en 1985.', '1549-03-29', '2024-04-30', false, 'STORY', 'ACTIVE', 4, 83);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (84, 'El Bastión Portugués del Río de la Plata', 'Colonia del Sacramento fue fundada en 1680 por el gobernador portugués Manuel Lobo frente a Buenos Aires, en la margen septentrional del Río de la Plata, con el objetivo estratégico de contrabandear mercancías y desafiar el monopolio comercial español en la región. Durante más de un siglo, la ciudad cambió de manos repetidamente entre portugueses y españoles en al menos siete ocasiones, convirtiéndose en uno de los escenarios centrales de la rivalidad ibérica por el control del estuario rioplatense. Su barrio histórico, con calles empedradas y arquitectura luso-española única en el continente, fue inscrito en la lista del Patrimonio de la Humanidad de la UNESCO en 1995.', '1680-01-20', '2024-03-03', false, 'STORY', 'ACTIVE', 1, 84);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (85, 'La Ciudad Heroína del Caribe Colonial', 'Cartagena de Indias fue fundada el 1 de junio de 1533 por Pedro de Heredia y se convirtió rápidamente en el puerto más importante del Caribe para el despacho de oro y plata hacia España, lo que la hizo blanco frecuente de piratas y potencias enemigas. En 1586 fue saqueada y parcialmente destruida por el corsario inglés Francis Drake, episodio que impulsó la construcción de las formidables murallas y fortines que aún rodean la ciudad histórica. El 11 de noviembre de 1811, Cartagena fue la primera ciudad de la Nueva Granada en declarar su independencia absoluta de España, siendo por ello denominada "La Heroica".', '1533-06-01', '2024-06-01', false, 'STORY', 'ACTIVE', 2, 85);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (86, 'La Gran Grieta de la Tierra', 'El Gran Cañón, tallado por el río Colorado a lo largo de seis millones de años, expone en sus paredes estratos de roca que representan casi dos mil millones de años de historia geológica de la Tierra. Diversas culturas indígenas, como los ancestrales puebloanos y posteriormente los havasupai, hualapai y navajo, habitaron sus recónditas grietas y mesetas durante miles de años antes de la llegada europea. El teniente Joseph Ives lideró en 1857 la primera expedición científica gubernamental al cañón, y en 1919 el presidente Woodrow Wilson lo proclamó Parque Nacional, sellando su protección perpetua.', '1919-02-26', '2024-07-14', false, 'INFORMATION', 'ACTIVE', 3, 86);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (87, 'Las Cataratas del Trueno de las Aguas', 'Las Cataratas del Niágara, formadas hace aproximadamente 12.000 años por el retroceso de los glaciares del último período glacial, fueron descritas por primera vez por escrito en 1683 por el explorador y sacerdote Louis Hennepin, quien quedó maravillado ante su estruendo y volumen de agua. Para los iroqueses y otros pueblos nativos de la región, las cataratas tenían un profundo significado espiritual y fueron escenario de rituales y ofrendas durante siglos. A partir del siglo XIX, la zona fronteriza entre Canadá y Estados Unidos se desarrolló industrialmente gracias a la potencia hidráulica de las cataratas, convirtiendo a Niágara Falls en pionera de la generación de electricidad a gran escala.', '0001-01-01', '2024-08-19', false, 'INFORMATION', 'ACTIVE', 4, 87);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (88, 'El Primer Parque Nacional del Mundo', 'La meseta de Yellowstone alberga el sistema geotérmico más grande del mundo, con más de 10.000 características hidrotermales que incluyen géiseres, fuentes termales y fumarolas, producto del supervolcán que yace bajo su superficie. Los pueblos shoshone y otros grupos nativos americanos habitaron y utilizaron la región durante al menos 11.000 años, valorando sus aguas termales con fines curativos y ceremoniales. El 1 de marzo de 1872, el presidente Ulysses S. Grant firmó la ley que convirtió a Yellowstone en el primer Parque Nacional del mundo, estableciendo un precedente histórico para la conservación de la naturaleza a nivel global.', '1872-03-01', '2024-09-01', false, 'INFORMATION', 'ACTIVE', 1, 88);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (89, 'Tenochtitlan: La Venecia del Nuevo Mundo', 'Tenochtitlan fue fundada en 1325 por los mexicas sobre un islote del lago Texcoco, según la leyenda guiados por el presagio divino de un águila devorando una serpiente sobre un nopal. En su apogeo a principios del siglo XVI, era una de las ciudades más grandes del mundo con más de 200.000 habitantes, conectada al continente por enormes calzadas y abastecida por un sofisticado sistema de chinampas agrícolas. Hernán Cortés la destruyó casi por completo entre 1519 y 1521, construyendo sobre sus ruinas la capital del Virreinato de Nueva España, aunque los cimientos aztecas emergen constantemente bajo las calles del moderno Zócalo capitalino.', '1325-01-01', '2024-02-10', false, 'STORY', 'ACTIVE', 2, 89);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (90, 'Las Gargantas del Pueblo Rarámuri', 'La Barranca del Cobre, o Copper Canyon, es un sistema de cañones en la Sierra Tarahumara del estado de Chihuahua que en conjunto es cuatro veces más grande que el Gran Cañón del Colorado, con profundidades que superan los 1.800 metros. El pueblo rarámuri, también conocido como tarahumara, ha habitado estas barrancas durante siglos, desarrollando una cultura de resistencia que les permitió replegarse hacia las profundidades del cañón para escapar de la colonización española en el siglo XVII. La construcción del Ferrocarril Chihuahua al Pacífico, inaugurado en 1961 tras décadas de obras que vencieron la extrema dificultad del terreno, abrió la región al turismo sin desplazar por completo a las comunidades rarámuri.', '1961-11-24', '2024-05-05', false, 'STORY', 'ACTIVE', 3, 90);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (91, 'La Ciudad Maya Frente al Mar', 'Tulum, conocida en tiempos prehispánicos como Zamá (amanecer), fue una de las pocas ciudades mayas construidas directamente sobre los acantilados del mar Caribe, funcionando como importante puerto comercial durante el período Posclásico entre los siglos XIII y XV d.C. Sus templos y el célebre Castillo, orientados con precisión astronómica, sirvieron probablemente como faros naturales para guiar las canoas comerciales que surcaban las costas de la península de Yucatán. Los españoles la avistaron en 1518 durante la expedición de Juan de Grijalva, describiendo sus imponentes edificios pintados de blanco, rojo y azul como una ciudad comparable en grandeza a Sevilla.', '1518-01-01', '2024-10-02', false, 'STORY', 'ACTIVE', 4, 91);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (92, 'El Esplendor Maya en la Selva', 'Palenque, llamada Lakamha (grandes aguas) por los mayas, alcanzó su máximo esplendor entre los siglos VI y VIII d.C. bajo el reinado del famoso gobernante Pakal el Grande, quien ascendió al trono a los doce años en 615 d.C. y gobernó durante 68 años transformando la ciudad en una de las más refinadas del mundo maya. Su tumba, descubierta en 1952 por el arqueólogo Alberto Ruz Lhuillier dentro del Templo de las Inscripciones, contenía uno de los ajuares funerarios más espléndidos hallados en Mesoamérica, con una máscara de jade y un sarcófago tallado de incomparable riqueza iconográfica. Los glifos mayas de Palenque han sido fundamentales para el desciframiento de la escritura maya y la reconstrucción de la historia dinástica del período Clásico.', '0615-07-29', '2024-11-17', false, 'INFORMATION', 'ACTIVE', 1, 92);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (93, 'La Cuna de la América Francesa', 'Quebec fue fundada el 3 de julio de 1608 por el explorador Samuel de Champlain sobre un asentamiento algonquino llamado Kébec, significando "donde el río se estrecha", convirtiéndose en la primera ciudad permanente de la Nueva Francia y el corazón de la colonización francesa en América del Norte. El 13 de septiembre de 1759, las Llanuras de Abraham a las afueras de la ciudad fueron escenario de la batalla decisiva entre las fuerzas británicas del general Wolfe y las francesas del marqués de Montcalm, en la que ambos comandantes murieron y cuyo resultado selló el dominio británico sobre el Canadá francés. Su Ciudad Vieja, única ciudad amurallada al norte del río Bravo, fue declarada Patrimonio de la Humanidad por la UNESCO en 1985.', '1608-07-03', '2024-07-03', false, 'STORY', 'ACTIVE', 2, 93);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (94, 'El Primer Parque Nacional de Canadá', 'Los territorios de lo que hoy es el Parque Nacional Banff fueron habitados durante al menos 10.000 años por pueblos indígenas como los stoney nakoda, piegan y kainai, quienes conocían perfectamente los pasos de montaña de las Rocosas canadienses. El 8 de noviembre de 1883, tres trabajadores del Ferrocarril Canadiense del Pacífico descubrieron las aguas termales del lago Cave and Basin, desencadenando una disputa por su propiedad que llevó al gobierno canadiense a reservar el área en 1885. Así nació el primer parque nacional de Canadá, y uno de los primeros del mundo, bajo la convicción del primer ministro John A. Macdonald de que la naturaleza espectacular debía ser patrimonio de todos los canadienses.', '1885-11-25', '2024-08-28', false, 'INFORMATION', 'ACTIVE', 3, 94);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (95, 'La Ciudad del Jazz y el Mardi Gras', 'Nueva Orleans fue fundada en 1718 por el colonizador francés Jean-Baptiste Le Moyne de Bienville a orillas del Mississippi, y su historia estuvo marcada por el dominio sucesivo de Francia, España y finalmente Estados Unidos tras la venta de Luisiana de 1803, lo que le confirió una cultura única e irreductiblemente criolla. La ciudad se convirtió en el mayor puerto de esclavos de Norteamérica durante el siglo XIX y de sus comunidades afroamericanas emergió a principios del siglo XX el jazz, género musical que transformaría para siempre la cultura global. El huracán Katrina, en agosto de 2005, devastó el 80% de la ciudad e inundó barrios históricos, representando una de las peores catástrofes naturales y sociales de la historia estadounidense reciente.', '1718-05-07', '2024-02-13', false, 'STORY', 'ACTIVE', 4, 95);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (96, 'El Último Sueño del Al-Ándalus', 'La Alhambra, cuyo nombre árabe al-Hamra significa "la roja" por el color de los materiales con que fue construida, comenzó a erigirse en el siglo XIII como palacio-fortaleza de los nazaríes, última dinastía musulmana de la península ibérica, alcanzando su máximo esplendor bajo el reinado de Yusuf I y Muhammad V en el siglo XIV. Sus palacios interiores, con el Patio de los Leones como obra cumbre de la arquitectura hispanomusulmana, representan el punto más refinado del arte nazarí, con su compleja decoración de mocárabes, epigrafía coránica y geometría simbólica. El 2 de enero de 1492, el último sultán nazarí Boabdil entregó las llaves de la Alhambra a los Reyes Católicos, poniendo fin a casi ocho siglos de presencia islámica en la península ibérica.', '1492-01-02', '2024-01-02', false, 'STORY', 'ACTIVE', 1, 96);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (97, 'La Serenísima República del Adriático', 'Venecia fue fundada en el siglo V d.C. por refugiados que huían de las invasiones de los hunos y los ostrogodos, estableciéndose sobre un archipiélago de 118 islas en la laguna adriática y construyendo una ciudad única en el mundo sobre pilotes de madera hincados en el fango. Durante los siglos XII al XV, la República de Venecia fue la potencia comercial y naval dominante del Mediterráneo oriental, controlando el lucrativo comercio de especias con Oriente e imponiendo su hegemonía desde el Adriático hasta Chipre y Creta. Napoleón Bonaparte puso fin a más de mil años de independencia de la Serenísima República el 12 de mayo de 1797, cuando Venecia se rindió sin combatir ante las tropas francesas, cerrando el capítulo más glorioso de su historia.', '0421-04-25', '2024-04-25', false, 'STORY', 'ACTIVE', 2, 97);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (98, 'El Templo de la Monarquía Absoluta', 'El Palacio de Versalles comenzó siendo un modesto pabellón de caza del rey Luis XIII, pero fue transformado por su hijo Luis XIV, el Rey Sol, en el palacio más grandioso de Europa, convirtiendo la corte francesa en símbolo absoluto del poder monárquico y del esplendor barroco a partir de 1682 cuando la trasladó allí desde París. Sus 700 habitaciones, 2.000 ventanas y jardines geométricos de André Le Nôtre que se extienden por 800 hectáreas sirvieron de modelo para las cortes europeas y consolidaron el francés como lengua diplomática universal durante dos siglos. El 28 de junio de 1919, el Salón de los Espejos fue escenario de la firma del Tratado de Versalles que puso fin a la Primera Guerra Mundial, cerrando con la humillación de Alemania un ciclo histórico iniciado en el mismo salón en 1871.', '1682-05-06', '2024-05-06', false, 'INFORMATION', 'ACTIVE', 3, 98);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (99, 'Seis Siglos de Piedra Gótica', 'La Catedral de Colonia, dedicada a San Pedro y a la Virgen María, comenzó a construirse el 15 de agosto de 1248 para albergar las reliquias de los Reyes Magos traídas desde Milán en 1164, pero las obras se interrumpieron durante 634 años y solo se completaron en 1880, convirtiéndola en un símbolo de la paciencia y la fe gótica alemana. Con sus agujas gemelas de 157 metros fue el edificio más alto del mundo al ser terminada, ostentando ese récord durante cuatro años hasta la construcción de la Aguja de Washington. Durante los bombardeos aliados de la Segunda Guerra Mundial, la ciudad de Colonia fue destruida en un 90%, pero la catedral sobrevivió casi intacta pese a haber recibido catorce impactos de bombas, lo que muchos consideraron un milagro.', '1248-08-15', '2024-08-15', false, 'INFORMATION', 'ACTIVE', 4, 99);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (100, 'El Corazón de Bohemia', 'El Castillo de Praga, fundado alrededor del año 880 por el príncipe Bořivoj de la dinastía Přemyslid, es el complejo castillo antiguo más grande del mundo con sus 70.000 metros cuadrados y ha sido sede del poder bohemio, imperial y posteriormente checo durante más de doce siglos. En 1618, la Segunda Defenestración de Praga, cuando funcionarios católicos fueron lanzados por las ventanas del castillo por nobles protestantes bohemios, desencadenó la Guerra de los Treinta Años que devastó Europa Central durante tres décadas. Tras la Revolución de Terciopelo de noviembre de 1989, el escritor y dramaturgo Václav Havel fue elegido presidente y estableció su residencia en el castillo, cerrando el ciclo del dominio comunista checoslovaco.', '0880-01-01', '2024-09-28', false, 'STORY', 'ACTIVE', 1, 100);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (101, 'El Símbolo de la Democracia Parlamentaria', 'El Palacio de Westminster, sede del Parlamento británico, fue construido a orillas del Támesis en estilo neogótico tras el devastador incendio que destruyó el edificio medieval en 1834, siendo inaugurado en 1870 con la Torre de Isabel, popularmente conocida como Big Ben por la gran campana de 13 toneladas que alberga. El parlamento inglés tiene raíces en la Carta Magna de 1215, cuando los barones obligaron al rey Juan sin Tierra a limitar su poder absoluto, y en la convocatoria del primer Parlamento representativo de Simon de Montfort en 1265. La tradición parlamentaria británica, consolidada tras la Revolución Gloriosa de 1688, se convirtió en modelo para las democracias constitucionales de todo el mundo.', '1834-10-16', '2024-10-16', false, 'INFORMATION', 'ACTIVE', 2, 101);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (102, 'La Perla del Adriático', 'Dubrovnik, conocida en la Edad Media como Ragusa, fue durante siglos una república mercantil independiente que rivalizó con Venecia en el control del comercio adriático y mediterráneo, alcanzando su máximo esplendor entre los siglos XIV y XVI gracias a una sofisticada diplomacia que le permitió mantener su independencia entre los imperios otomano y habsburgo. Sus imponentes murallas de hasta seis metros de espesor, construidas y reforzadas entre los siglos XIII y XVI, resistieron el devastador terremoto de 1667 que destruyó gran parte de la ciudad y mató a más de 5.000 personas, aunque fueron reconstruidas en gran parte. En 1991, durante la guerra de independencia croata, la ciudad fue sometida a un asedio de siete meses por las fuerzas del Ejército Popular Yugoslavo, sufriendo daños significativos en su patrimonio histórico.', '1991-10-01', '2024-06-24', false, 'STORY', 'ACTIVE', 3, 102);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (103, 'Monasterios Suspendidos entre Cielo y Tierra', 'Meteora, cuyo nombre griego significa "suspendido en el aire" o "en los cielos", es un conjunto de formaciones rocosas de arenisca que se elevan hasta 600 metros sobre la llanura de Tesalia, en cuyas cimas se construyeron entre los siglos XIV y XVI veinticuatro monasterios ortodoxos para refugio de monjes que huían de las invasiones otomanas. El primer ermitaño conocido en habitarlas fue el monje Barnabas en el siglo X, quien se instaló en cuevas naturales; la gran época constructiva llegó con la llegada del monje Atanasio y la fundación del monasterio de la Gran Meteoron alrededor de 1344. Los monasterios, a los que se accedía originalmente solo mediante redes y cuerdas elevadas manualmente, conservan valiosos frescos bizantinos y manuscritos iluminados de incalculable valor histórico.', '1344-01-01', '2024-03-25', false, 'INFORMATION', 'ACTIVE', 4, 103);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (104, 'La Ciudad Congelada por el Vesubio', 'Pompeya fue una próspera ciudad romana de unos 11.000 habitantes situada a los pies del volcán Vesubio, que el 24 de agosto del año 79 d.C. entró en erupción sepultando la ciudad bajo una lluvia de cenizas y pómez de hasta seis metros de profundidad, matando a más de 2.000 personas y preservando bajo su manto la instantánea perfecta de la vida romana del siglo I. La ciudad, olvidada durante siglos, fue redescubierta accidentalmente en 1748 durante obras de canalización ordenadas por el rey Carlos III de Nápoles, dando inicio a excavaciones sistemáticas que continúan hasta hoy y han revelado edificios, frescos, mosaicos y hasta el contenido de hornos de pan perfectamente conservados. Los célebres moldes de yeso de las víctimas, creados por el arqueólogo Giuseppe Fiorelli en 1863 vertiendo escayola en los huecos dejados por los cuerpos descompuestos, produjeron una de las imágenes más estremecedoras y humanizadoras de la historia.', '0079-08-24', '2024-08-24', false, 'STORY', 'ACTIVE', 1, 104);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (105, 'El Pueblo que le Dio Nombre a una Era', 'Hallstatt, orillando el lago Hallstätter See en el Salzkammergut austriaco, es uno de los asentamientos humanos habitados más antiguos de Europa Central, con evidencias de extracción de sal que se remontan al año 5.000 a.C., un recurso tan valioso en la antigüedad que fue llamado "el oro blanco". La cultura Hallstatt, período de la Edad del Hierro temprano entre 800 y 450 a.C. caracterizado por la expansión de los celtas en Europa, lleva el nombre de este lugar por los miles de objetos arqueológicos de extraordinaria riqueza encontrados en su necrópolis. El idílico pueblo de apenas 800 habitantes, con sus casas de madera reflejadas en las aguas del lago, fue declarado Patrimonio de la Humanidad por la UNESCO en 1997 y hoy es uno de los destinos turísticos más fotografiados del mundo.', '0001-01-01', '2024-05-18', false, 'INFORMATION', 'ACTIVE', 2, 105);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (106, 'La Mayor Catarata de Europa', 'Las Cataratas del Rhin, situadas cerca de la ciudad de Schaffhausen en el norte de Suiza, son la cascada de mayor caudal de Europa con sus 150 metros de anchura y una caída de unos 23 metros que arroja hasta 600 metros cúbicos de agua por segundo en periodo de deshielo. La región fue habitada en la antigüedad por celtas y romanos, que establecieron un importante puesto militar en la orilla norte del Rhin, y durante la Edad Media el señorío del castillo de Laufen controlaba el paso de mercancías por este enclave estratégico. El artista inglés J.M.W. Turner las pintó en 1802 durante su Grand Tour por Europa, contribuyendo decisivamente a popularizarlas entre la aristocracia y la intelectualidad romántica del siglo XIX.', '0001-01-01', '2024-07-22', false, 'INFORMATION', 'ACTIVE', 3, 106);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (107, 'El Templo Mundial de la Ópera', 'La Ópera Estatal de Viena, inaugurada el 25 de mayo de 1869 con "Don Giovanni" de Mozart ante el emperador Francisco José I, fue el edificio inaugural de la Ringstrasse, el grandioso bulevar neoclásico con el que el monarca transformó Viena en la capital imperial más bella de Europa. Los arquitectos August Sicard von Sicardsburg y Eduard van der Nüll fueron tan devastados por las críticas iniciales a su diseño que van der Nüll se suicidó semanas antes de la inauguración, y Sicardsburg murió de un infarto dos meses después. Casi completamente destruida por los bombardeos aliados en marzo de 1945, la ópera fue reconstruida fielmente y reinaugurada el 5 de noviembre de 1955 con "Fidelio" de Beethoven, coincidiendo simbólicamente con la restauración de la soberanía austriaca.', '1869-05-25', '2024-05-25', false, 'STORY', 'ACTIVE', 4, 107);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (108, 'El Lago del Misterio Escocés', 'El lago Ness, con sus 37 kilómetros de longitud y una profundidad de hasta 230 metros, es el mayor cuerpo de agua de Gran Bretaña por volumen y fue formado por el movimiento de la falla geológica del Gran Glen hace aproximadamente 10.000 años. La primera referencia escrita a un "monstruo" en sus aguas aparece en la "Vida de San Columba" del año 565 d.C., cuando el abad irlandés supuestamente ahuyentó a una bestia del río Ness, convirtiéndose en el origen del mito moderno de "Nessie". La fotografía del "cirujano", publicada en el Daily Mail en 1934 y que mostraba supuestamente el cuello y la cabeza del monstruo, fue revelada como un fraude en 1994, aunque el mito sigue atrayendo a más de 500.000 turistas anuales a las orillas del lago.', '0565-01-01', '2024-10-31', false, 'STORY', 'ACTIVE', 1, 108);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (109, 'Las Terrazas de Agua Turquesa de Croacia', 'Los Lagos de Plitvice, sistema de dieciséis lagos escalonados interconectados por cascadas en el interior de Croacia, fueron formados durante miles de años por la acumulación de travertino, una roca caliza porosa depositada por las algas y bacterias que viven en sus aguas, creando barreras naturales que elevan constantemente el nivel de los lagos. La región fue habitada desde la prehistoria y durante la Edad Media fue escenario de frecuentes batallas entre los reinos croata, húngaro y otomano por el control de este paso estratégico entre la costa dálmata y el interior continental. Declarado Parque Nacional en 1949, el primer sitio de la ex Yugoslavia en serlo, los Lagos de Plitvice fueron incluidos por la UNESCO en su lista de Patrimonio de la Humanidad en 1979.', '1949-04-08', '2024-04-15', false, 'INFORMATION', 'ACTIVE', 2, 109);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (110, 'El Volcán que Enterró a Roma', 'El Monte Vesubio, el único volcán activo de Europa continental, ha hecho erupción al menos treinta veces desde la catastrófica del año 79 d.C. que sepultó Pompeya y Herculano, siendo especialmente violentas las de 472, 1631 y 1944, esta última durante la Segunda Guerra Mundial frente a las tropas aliadas que acababan de liberar Nápoles. Los romanos ignoraban por completo la naturaleza volcánica del Vesubio, que consideraban simplemente una montaña con una cima inusualmente plana; el mismo Plinio el Joven, cuyo tío Plinio el Viejo murió intentando rescatar a sobrevivientes, describió con extraordinaria precisión científica la erupción en cartas al historiador Tácito. En la actualidad, más de 600.000 personas viven en la "zona roja" a los pies del volcán, considerada una de las zonas de mayor riesgo volcánico del mundo.', '0079-08-24', '2024-08-24', false, 'INFORMATION', 'ACTIVE', 3, 110);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (111, 'La Acrópolis Sobre el Mar Egeo', 'La Acrópolis de Lindos, encaramada sobre un promontorio rocoso de 116 metros de altitud en la isla de Rodas, fue uno de los principales santuarios del Mediterráneo antiguo dedicado a Atenea Lindia, cuyas raíces se remontan al período micénico del siglo IX a.C. La ciudad-estado de Lindos fue en los siglos VII y VI a.C. una potencia naval y comercial que estableció colonias en Sicilia y la costa de Anatolia, y su legislador Cleóbulo fue incluido entre los Siete Sabios de Grecia. Los Caballeros Hospitalarios, que controlaron Rodas entre 1309 y 1522, construyeron una fortaleza medieval sobre las ruinas clásicas de la acrópolis, fusionando en un mismo recinto el legado griego, helenístico, romano y medieval.', '0001-01-01', '2024-09-10', false, 'INFORMATION', 'ACTIVE', 4, 111);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (112, 'El Puente que Dio Nombre a una Ciudad', 'El Stari Most, o Puente Viejo de Mostar, fue construido entre 1557 y 1566 por el arquitecto otomano Mimar Hayruddin por encargo de Solimán el Magnífico, siendo durante más de cuatro siglos el puente de arco de piedra de mayor vano del mundo, con sus 29 metros de luz sobre el río Neretva. El nombre de la propia ciudad de Mostar deriva precisamente de los "mostari", los guardias del puente, que vigilaban este paso estratégico en el corazón de Bosnia Herzegovina. El 9 de noviembre de 1993, durante la guerra de Bosnia, las fuerzas del Consejo Croata de Defensa lo destruyeron deliberadamente con artillería; fue reconstruido meticulosamente con piedras originales recuperadas del río y reinaugurado en 2004, siendo declarado Patrimonio de la Humanidad por la UNESCO.', '1566-01-01', '2024-11-09', false, 'STORY', 'ACTIVE', 1, 112);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (113, 'El Mayor Campo de Exterminio Nazi', 'Auschwitz-Birkenau, establecido por las SS alemanas en la ciudad polaca de Oświęcim en junio de 1940, fue el mayor complejo de campos de concentración y exterminio del régimen nacionalsocialista, donde entre 1940 y 1945 fueron asesinadas aproximadamente 1,1 millones de personas, en su inmensa mayoría judíos europeos, pero también polacos, sinti y romani, soviéticos y prisioneros de otras nacionalidades. Las instalaciones industriales de muerte, que incluían cámaras de gas y hornos crematorios de enorme capacidad, representan el punto más oscuro del Holocausto, el genocidio sistemático de seis millones de judíos orquestado por el régimen nazi. El campo fue liberado por el Ejército Rojo soviético el 27 de enero de 1945, fecha que la ONU designó en 2005 como el Día Internacional de Conmemoración del Holocausto.', '1940-06-14', '2024-01-27', false, 'STORY', 'ACTIVE', 2, 113);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (114, 'La Joya Medieval del Báltico', 'Tallin, llamada Reval durante la Edad Media, fue fundada por el rey dinamarqués Valdemar II en 1219 sobre un asentamiento estonio preexistente, y su ciudad alta o Toompea fue fortín sucesivo de daneses, caballeros teutónicos, suecos y rusos a lo largo de seis siglos de dominación extranjera. Su ciudad baja, habitada por mercaderes de la Liga Hanseática desde el siglo XIII, conserva uno de los conjuntos medievales mejor preservados del norte de Europa, con sus murallas, torres, iglesias góticas y la célebre farmacia de Raeapteek, una de las más antiguas del mundo en funcionamiento desde 1422. El 23 de agosto de 1989, los estonios, letones y lituanos formaron una cadena humana de 675 kilómetros llamada "La Vía Báltica" que atravesaba los tres países, reclamando pacíficamente la independencia de la Unión Soviética.', '1219-01-01', '2024-08-23', false, 'STORY', 'ACTIVE', 3, 114);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (115, 'El Palacio de los Sueños Románticos Portugueses', 'Sintra, enclavada en las sierras de la Arrábida a apenas 28 kilómetros de Lisboa, fue desde la antigüedad un lugar sagrado para los celtas, que la denominaban "Monte de la Luna", y posteriormente residencia de verano de los reyes moros y luego de los monarcas portugueses durante más de cinco siglos. El Palacio Nacional de Sintra, con sus peculiares chimeneas cónicas que dominan el skyline de la villa, es el palacio medieval mejor conservado de Portugal y fue residencia real casi continua desde el siglo XIV hasta el siglo XIX. El poeta inglés Lord Byron, que la visitó en 1809 durante la Guerra Peninsular, la describió como "la más hermosa tierra que he visto", contribuyendo a popularizarla entre los románticos europeos y al gran turismo aristocrático del siglo XIX.', '0001-01-01', '2024-06-10', false, 'INFORMATION', 'ACTIVE', 4, 115);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (116, 'El Fiordo Más Espectacular de Escandinavia', 'El Fiordo de Geiranger, esculpido hace aproximadamente 10.000 años por los glaciares del último período glacial, se extiende 15 kilómetros tierra adentro entre paredes rocosas de hasta 1.400 metros de altura cubiertas de cascadas que caen directamente al mar, las más famosas de las cuales reciben nombres evocadores como "Los Siete Hermanos" y "El Novio". Los vikingos utilizaron los fiordos noruegos como rutas naturales de navegación desde el siglo VIII, y el de Geiranger alberga granjas colgadas en las laderas que fueron habitadas hasta bien entrado el siglo XX, accesibles únicamente por difíciles senderos de montaña. En 2005, la UNESCO lo declaró Patrimonio de la Humanidad junto con el fiordo de Nærøy, reconociendo que representan algunos de los paisajes naturales más sublimes del planeta.', '0001-01-01', '2024-07-16', false, 'INFORMATION', 'ACTIVE', 1, 116);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (117, 'La Cima más Fotografiada de los Alpes', 'El Matterhorn, con sus 4.478 metros de altitud y su silueta piramidal perfecta en la frontera entre Suiza e Italia, fue durante siglos considerado un monte imposible e incluso maldito por las comunidades alpinas que lo contemplaban desde los valles de Zermatt y Breuil. El alpinista inglés Edward Whymper encabezó el primer ascenso exitoso el 14 de julio de 1865, pero en el descenso cuatro de sus siete compañeros cayeron al vacío por el rompimiento de una cuerda, en la tragedia más famosa de la historia del alpinismo, que conmocionó a toda Europa. Hoy en día más de 3.000 alpinistas coronan el Matterhorn cada año, aunque la montaña sigue cobrándose en torno a diez vidas anuales, manteniendo su reputación de montaña más peligrosa de los Alpes.', '1865-07-14', '2024-07-14', false, 'STORY', 'ACTIVE', 2, 117);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (118, 'La Torre que Desafía la Gravedad', 'La Torre de Pisa, el campanario de mármol blanco de la catedral de Santa María Asunta, comenzó a construirse en 1173 y ya durante su construcción comenzó a inclinarse por la blandura del suelo arcilloso, lo que llevó a interrumpir las obras en varias ocasiones durante casi dos siglos antes de su finalización en 1372. Paradójicamente, la inclinación que amenazó durante siglos con derruirla se ha convertido en su principal atractivo, y el físico Galileo Galilei utilizó supuestamente su plataforma superior hacia 1589 para realizar sus famosos experimentos sobre la caída libre de objetos. Entre 1990 y 2001, ingenieros de todo el mundo acometieron un delicado proceso de estabilización que redujo su inclinación de 5,5 a 3,97 grados, asegurando su supervivencia por al menos otros tres siglos.', '1173-08-09', '2024-08-09', false, 'INFORMATION', 'ACTIVE', 3, 118);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (119, 'La Ciudad de los Caballeros y los Santos', 'Ávila, situada a 1.131 metros sobre el nivel del mar en la meseta castellana, conserva la muralla medieval más completa del mundo, con sus 2.516 metros de perímetro, 88 torres semicirculares y nueve puertas construidas entre 1090 y 1099 bajo el mandato del rey Alfonso VI tras la Reconquista de Toledo. La ciudad fue también cuna de Santa Teresa de Jesús, nacida en 1515, quien fundó la Orden de las Carmelitas Descalzas reformando la vida religiosa española y cuya obra mística y literaria, escrita en un castellano de extraordinaria limpidez, la convirtió en una de las figuras más importantes de la Contrarreforma católica y en una de las primeras mujeres doctoras de la Iglesia. Su conjunto histórico fue declarado Patrimonio de la Humanidad por la UNESCO en 1985.', '1090-01-01', '2024-10-15', false, 'STORY', 'ACTIVE', 4, 119);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (120, 'El Castillo de Cuento de Hadas del Rey Loco', 'El Castillo de Neuschwanstein fue mandado construir por el rey Luis II de Baviera a partir de 1869 como refugio personal y homenaje romántico al compositor Richard Wagner y a las leyendas germánicas medievales que tanto admiraba, invirtiendo su fortuna personal en una obra que nunca llegaría a ver terminada. El rey Luis II, apodado el "Rey de los Sueños" o el "Rey Loco" por sus contemporáneos, fue declarado incapaz e internado en junio de 1886; al día siguiente apareció muerto junto a su psiquiatra en circunstancias jamás esclarecidas en el lago Starnberg. El castillo, que sirvió de inspiración directa a Walt Disney para el castillo de La Bella Durmiente, recibe cada año más de 1,4 millones de visitantes, convirtiéndose en el monumento más visitado de Alemania.', '1869-09-05', '2024-09-05', false, 'STORY', 'ACTIVE', 1, 120);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (121, 'El legado de Van Gogh en Amsterdam', 'El Museo Van Gogh de Amsterdam alberga la mayor colección del mundo de obras del pintor neerlandés Vincent van Gogh, inaugurada en 1973. Durante su corta vida, Van Gogh produjo más de 900 pinturas y 1.100 dibujos, muchos de los cuales se encuentran en este recinto. El museo fue diseñado por el arquitecto Gerrit Rietveld y ampliado posteriormente por Kisho Kurokawa en 1999.', '1973-06-02', '2024-01-15', false, 'INFORMATION', 'ACTIVE', 1, 121);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (122, 'Las apariciones de Fátima', 'El 13 de mayo de 1917, tres pastorcillos portugueses afirmaron haber visto a la Virgen María en la Cova da Iria, cerca de Fátima, dando inicio a una serie de apariciones que se repetirían hasta octubre de ese mismo año. El evento del 13 de octubre, conocido como el "Milagro del Sol", fue presenciado por aproximadamente 70.000 personas congregadas en el lugar. Hoy, el Santuario de Fátima es uno de los centros de peregrinación mariana más importantes del mundo, con millones de visitantes cada año.', '1917-05-13', '2024-02-20', false, 'STORY', 'ACTIVE', 2, 122);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (123, 'El techo que cambió el arte', 'Entre 1508 y 1512, Miguel Ángel Buonarroti pintó en soledad el célebre techo de la Capilla Sixtina por encargo del papa Julio II, representando escenas del Génesis en más de 500 metros cuadrados. La obra, que incluye la icónica "Creación de Adán", fue ejecutada sobre andamios a gran altura y supuso un esfuerzo físico y artístico sin precedentes. Décadas después, el propio Miguel Ángel regresaría para pintar "El Juicio Final" en el muro del altar, completado en 1541.', '1512-10-31', '2024-03-08', false, 'STORY', 'ACTIVE', 3, 123);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (124, 'La fortaleza sobre la roca volcánica', 'El Castillo de Edimburgo se alza sobre Castle Rock, un tapón volcánico formado hace más de 350 millones de años, siendo uno de los emplazamientos fortificados más antiguos de Europa con evidencias de ocupación desde el siglo XII a.C. A lo largo de la Edad Media fue escenario de numerosos asedios, incluyendo el célebre asalto de 1314 liderado por Thomas Randolph, sobrino de Robert Bruce, que reconquistó la fortaleza de manos inglesas. Hoy custodia las Joyas de la Corona de Escocia, los honores más antiguos de Gran Bretaña, en uso desde el siglo XV.', '1314-03-14', '2024-04-05', false, 'INFORMATION', 'ACTIVE', 4, 124);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (125, 'La isla de la niebla y los clanes', 'La isla de Skye, cuyo nombre gaélico "An t-Eilean Sgitheanach" significa "la isla alada", fue durante siglos territorio disputado entre los clanes MacLeod y MacDonald, cuyas rivalidades marcaron profundamente la historia de las Highlands escocesas. En 1746, tras la derrota jacobita en Culloden, el príncipe Bonnie Prince Charlie fue rescatado y llevado a Skye disfrazado de sirvienta por Flora MacDonald, en uno de los episodios más románticos de la historia escocesa. La isla fue unida al continente mediante el Puente de Skye en 1995, poniendo fin a siglos de aislamiento que habían preservado su cultura gaélica.', '1746-06-29', '2024-05-12', false, 'STORY', 'ACTIVE', 1, 125);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (126, 'El templo más grande del mundo', 'Angkor Wat fue construido en el siglo XII por el rey jemer Suryavarman II como templo hinduista dedicado a Vishnu, convirtiéndose en el edificio religioso más grande del mundo con una superficie de más de 400 hectáreas. A finales del siglo XII, el complejo fue reconvertido al budismo theravada, transformación que se refleja en las sucesivas capas de arte y arquitectura que aún pueden apreciarse. El templo fue redescubierto por Occidente en 1860 gracias al naturalista francés Henri Mouhot, aunque la población jemer nunca olvidó su existencia.', '1150-01-01', '2024-06-18', false, 'INFORMATION', 'ACTIVE', 2, 126);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (127, 'La leyenda del dragón descendente', 'Según la mitología vietnamita, la Bahía de Halong fue creada por un dragón enviado por los dioses para proteger a Vietnam de invasores, cuya cola golpeó la tierra formando los más de 1.600 islotes kársticos que emergen del mar de China Meridional. Históricamente, la bahía fue escenario de importantes batallas navales, incluyendo la victoria vietnamita sobre la flota mongola en 1288, cuando el general Trần Hưng Đạo utilizó estacas ocultas bajo el agua para hundir los barcos invasores. Declarada Patrimonio de la Humanidad por la UNESCO en 1994, la bahía alberga ecosistemas únicos y comunidades flotantes que han habitado sus aguas durante generaciones.', '1288-04-09', '2024-07-22', false, 'STORY', 'ACTIVE', 3, 127);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (128, 'La ciudad de los diez mil templos', 'Entre los siglos IX y XIII, la llanura de Bagan fue la capital del primer Imperio de Pagan, durante cuyo apogeo se construyeron más de 10.000 estructuras budistas en apenas 60 kilómetros cuadrados. El rey Anawrahta, fundador del imperio en 1044, introdujo el budismo theravada como religión oficial y patrocinó la construcción masiva de templos, pagodas y monasterios que transformaron Bagan en el centro espiritual del sudeste asiático. La invasión mongola de 1287 puso fin al Imperio de Pagan, aunque miles de las estructuras originales siguen en pie y conforman uno de los paisajes arqueológicos más impresionantes del mundo.', '1044-01-01', '2024-08-14', false, 'INFORMATION', 'ACTIVE', 4, 128);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (129, 'El mandala de piedra más grande del mundo', 'Borobudur, construido entre los siglos VIII y IX durante la dinastía Sailendra, es el templo budista más grande del mundo y un monumental mandala tridimensional que representa el camino hacia la iluminación según la cosmología budista. El complejo fue abandonado alrededor del siglo X, posiblemente debido a erupciones volcánicas y al desplazamiento del poder político hacia el este de Java, quedando sepultado bajo capas de ceniza y vegetación durante siglos. Fue redescubierto en 1814 por el gobernador colonial británico Thomas Stamford Raffles y restaurado extensamente durante el siglo XX con apoyo de la UNESCO.', '0800-01-01', '2024-09-03', false, 'INFORMATION', 'ACTIVE', 1, 129);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (130, 'La montaña sagrada del Japón', 'El Monte Fuji, con sus 3.776 metros de altura, es el volcán más alto de Japón y ha sido venerado como lugar sagrado desde tiempos inmemoriales, siendo mencionado en textos japoneses desde el siglo VIII. Durante el período Edo, el culto al Fuji se popularizó enormemente con la aparición de las asociaciones Fujiko, grupos de peregrinos que realizaban ascensiones rituales al cráter consideradas actos de purificación espiritual. La última erupción del volcán ocurrió en 1707, durante el llamado período Hōei, cuando una lluvia de ceniza cubrió Edo (actual Tokio) durante varias semanas.', '0700-01-01', '2024-10-01', false, 'STORY', 'ACTIVE', 2, 130);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (131, 'El ejército eterno del primer emperador', 'El Ejército de Terracota fue creado por orden del primer emperador de China unificada, Qin Shi Huang, para protegerle en el más allá, y fue enterrado junto a su monumental mausoleo alrededor del año 210 a.C. Se estima que el conjunto funerario incluye más de 8.000 soldados, 130 carros y 670 caballos de terracota, cada uno con rasgos faciales únicos e individualizados, lo que sugiere que podrían representar a soldados reales del ejército imperial. El descubrimiento accidental en 1974 por unos campesinos que excavaban un pozo fue considerado uno de los hallazgos arqueológicos más importantes del siglo XX.', '0001-01-01', '2024-11-07', false, 'INFORMATION', 'ACTIVE', 3, 131);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (132, 'El paisaje que inspiró mil pinturas', 'El valle del río Li, con sus características montañas kársticas de picos afilados que emergen entre la niebla, ha sido fuente de inspiración para pintores y poetas chinos desde la dinastía Tang (siglos VII-X), convirtiéndose en símbolo visual de la estética paisajística china. El paisaje entre Guilin y Yangshuo fue durante siglos una ruta comercial fluvial vital para el sur de China, comunicando la cuenca del río Perla con el interior del país. Hoy el paisaje del río Li aparece en el reverso del billete de 20 yuanes chinos, evidenciando la profunda identidad cultural que este territorio representa para la nación.', '0001-01-01', '2024-12-05', false, 'STORY', 'ACTIVE', 4, 132);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (133, 'Las ciudades subterráneas de Anatolia', 'La región de Capadocia debe su singular paisaje de chimeneas de hadas y valles esculpidos a millones de años de actividad volcánica y erosión, pero fue la mano humana la que excavó en esa roca blanda miles de viviendas, iglesias y ciudades subterráneas desde la antigüedad. Durante los primeros siglos del cristianismo, comunidades de monjes y fieles perseguidos excavaron ciudades subterráneas como Derinkuyu y Kaymaklı, capaces de albergar a miles de personas con establos, bodegas, iglesias y sistemas de ventilación. En el período bizantino, Capadocia se convirtió en un importante centro monástico con cientos de iglesias rupestres decoradas con frescos, muchos de los cuales se conservan hasta hoy.', '0300-01-01', '2024-01-28', false, 'INFORMATION', 'ACTIVE', 1, 133);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (134, 'La gran iglesia del mundo antiguo', 'La Basílica de Hagia Sophia fue construida por orden del emperador bizantino Justiniano I entre 532 y 537 d.C., convirtiéndose durante casi mil años en la catedral cristiana más grande del mundo y en el principal templo del Patriarcado Ecuménico de Constantinopla. Tras la conquista otomana de Constantinopla en 1453, el sultán Mehmed II ordenó su conversión en mezquita, añadiéndose los cuatro minaretes exteriores que hoy la caracterizan, mientras los mosaicos cristianos fueron cubiertos con enlucido. En 1934, Mustafa Kemal Atatürk la transformó en museo como símbolo del estado laico turco, condición que se mantuvo hasta su reconversión en mezquita en 2020.', '0537-12-27', '2024-02-14', false, 'STORY', 'ACTIVE', 2, 134);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (135, 'El castillo de algodón y las aguas termales', 'Pamukkale, cuyo nombre turco significa "castillo de algodón", es una formación natural de terrazas de travertino creadas por el depósito de carbonato de calcio de las aguas termales que brotan a 35 grados centígrados, en un proceso que lleva miles de años. Junto a estas terrazas se levantó la antigua ciudad grecorromana de Hierápolis, fundada en el siglo II a.C. como ciudad balnearia por los reyes de Pérgamo, donde las aguas termales eran consideradas sagradas y curativas. Las ruinas de Hierápolis incluyen uno de los teatros romanos mejor conservados de Asia Menor, con capacidad para 12.000 espectadores, además de una extensa necrópolis con miles de sarcófagos.', '0001-01-01', '2024-03-22', false, 'INFORMATION', 'ACTIVE', 3, 135);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (136, 'La ciudad rosa tallada en la roca', 'Petra fue la capital del reino nabateo, un pueblo árabe que dominó las rutas comerciales del incienso y las especias entre Arabia, Egipto y el Mediterráneo desde el siglo IV a.C., acumulando una riqueza extraordinaria que se refleja en sus monumentales tumbas y templos tallados directamente en la arenisca rojiza. En el año 106 d.C., el emperador romano Trajano anexionó el reino nabateo como provincia de Arabia Pétrea, integrando Petra en el Imperio Romano y añadiendo elementos arquitectónicos clásicos a la ciudad. La ciudad fue abandonada gradualmente tras varios terremotos y el desplazamiento de las rutas comerciales, y permaneció prácticamente desconocida para Occidente hasta que el explorador suizo Johann Ludwig Burckhardt la redescubrió en 1812.', '0001-01-01', '2024-04-19', false, 'STORY', 'ACTIVE', 4, 136);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (137, 'La ciudad eterna a orillas del Ganges', 'Varanasi, conocida también como Benarés o Kashi, es considerada una de las ciudades habitadas de forma continua más antiguas del mundo, con una historia documentada que se remonta al menos al siglo XI a.C., y para los hinduistas es la ciudad más sagrada de la tierra, donde morir garantiza la liberación del ciclo de reencarnaciones. Fue en los alrededores de Varanasi donde Siddhartha Gautama pronunció su primer sermón tras alcanzar la iluminación, en el lugar conocido como Sarnath, estableciendo así las bases del budismo alrededor del siglo V a.C. El río Ganges, que baña los célebres ghats de la ciudad, es venerado como diosa en el hinduismo y sus aguas se consideran purificadoras de todos los pecados.', '0001-01-01', '2024-05-30', false, 'INFORMATION', 'ACTIVE', 1, 137);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (138, 'La capital del último gran imperio hindú', 'Hampi fue la capital del Imperio Vijayanagara, el último gran reino hindú del sur de la India, que entre los siglos XIV y XVI gobernó sobre la mayor parte del subcontinente indio y fue, según los viajeros de la época, una de las ciudades más grandes y ricas del mundo medieval. En 1565, una coalición de cinco sultanatos musulmanes del Decán derrotó al ejército de Vijayanagara en la batalla de Talikota, tras la cual la ciudad fue saqueada y destruida durante meses, quedando reducida a las ruinas que hoy pueden contemplarse. Entre los monumentos que sobrevivieron destaca el Templo Virupaksha, dedicado al dios Shiva, que ha estado en uso continuo desde el siglo VII y permanece activo como lugar de culto hasta la actualidad.', '1336-01-01', '2024-06-25', false, 'STORY', 'ACTIVE', 2, 138);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (139, 'El templo sobre el mar', 'El Templo Tanah Lot, cuyo nombre en balinés significa "tierra en medio del mar", fue construido según la tradición en el siglo XVI por el sacerdote hindú Nirartha, quien durante su peregrinación por Bali eligió este islote rocoso batido por las olas como lugar sagrado de culto a los dioses del mar. El templo forma parte de una cadena de siete templos marinos que, según la cosmovisión balinesa, protegen espiritualmente la isla de las fuerzas del mar y los malos espíritus, siendo Tanah Lot el más visitado y fotografiado de todos ellos. La serpiente marina sagrada que, según la leyenda, Nirartha transformó de su faja para proteger el templo, es representada simbólicamente por las cobras reales que aún habitan las cuevas bajo la roca.', '1550-01-01', '2024-07-11', false, 'INFORMATION', 'ACTIVE', 3, 139);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (140, 'La roca del león y el palacio en las alturas', 'Sigiriya, o "roca del león" en cingalés, es una formación rocosa de 200 metros de altura sobre la que el rey Kashyapa I construyó entre 477 y 495 d.C. una fortaleza-palacio inexpugnable, rodeada de jardines acuáticos que se consideran uno de los primeros ejemplos de planificación paisajística del mundo. Según las crónicas budistas del Mahavamsa, Kashyapa eligió esta roca inaccesible como residencia por temor a la venganza de su hermano Moggallana, a quien había despojado del trono tras asesinar a su padre. Tras la muerte de Kashyapa en combate en 495 d.C., el palacio fue abandonado y convertido en monasterio budista, función que mantuvo durante siglos hasta su abandono definitivo alrededor del siglo XIV.', '0477-01-01', '2024-08-29', false, 'STORY', 'ACTIVE', 4, 140);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (141, 'La capital del reino siamés', 'Ayutthaya fue fundada en 1350 por el rey Ramathibodi I como capital del reino de Siam, y durante más de cuatro siglos fue uno de los centros comerciales y diplomáticos más importantes del sudeste asiático, recibiendo embajadas de Europa, China, Japón y Persia. En 1767, las tropas birmanas del rey Hsinbyushin conquistaron y destruyeron metódicamente la ciudad tras un asedio de más de un año, derritiendo las imágenes de Buda doradas para extraer el metal y decapitando sistemáticamente las estatuas, lo que explica el característico aspecto de las ruinas actuales. Tras la caída de Ayutthaya, el rey Taksin estableció una nueva capital en Thonburi, y posteriormente Bangkok se convirtió en la sede del nuevo reino de Siam bajo la dinastía Chakri.', '1350-03-04', '2024-09-17', false, 'INFORMATION', 'ACTIVE', 1, 141);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (142, 'El puerto de las sedas y las especias', 'Hoi An, conocida en tiempos antiguos como Faifo, fue entre los siglos XV y XIX uno de los puertos comerciales más activos del sudeste asiático, donde mercaderes chinos, japoneses, holandeses, portugueses y árabes intercambiaban seda, cerámica, especias y madera de agar. La excepcional conservación de su casco histórico se debe en parte a que el puerto fue perdiendo importancia comercial a medida que el río se fue sedimentando, lo que evitó el reemplazo de los edificios antiguos por construcciones modernas. La ciudad antigua de Hoi An fue declarada Patrimonio de la Humanidad por la UNESCO en 1999, siendo reconocida como ejemplo excepcional de puerto comercial asiático donde las culturas se fusionaron para crear una arquitectura y tradiciones únicas.', '1400-01-01', '2024-10-23', false, 'STORY', 'ACTIVE', 2, 142);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (143, 'La ciudad real del Mekong', 'Luang Prabang fue la capital del reino de Lan Xang, el "Reino del Millón de Elefantes", fundado en 1353 por el rey Fa Ngum, quien unificó los principados laosianos y estableció el budismo theravada como religión oficial importando desde Camboya la sagrada imagen del Prabang que dio nombre a la ciudad. La ciudad fue durante siglos el centro espiritual y cultural de Laos, con más de 30 monasterios budistas activos en un área urbana relativamente pequeña, tradición que se mantiene viva en la ceremonia diaria del Tak Bat, donde los monjes recorren las calles al amanecer recibiendo ofrendas de arroz. Declarada Patrimonio de la Humanidad en 1995, la ciudad ejemplifica la fusión entre la arquitectura laosiana tradicional y la herencia colonial francesa del siglo XIX.', '1353-01-01', '2024-11-14', false, 'INFORMATION', 'ACTIVE', 3, 143);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (144, 'La residencia de los Dalái Lamas', 'El Palacio Potala, que se eleva sobre la colina Marpo Ri a 3.700 metros de altitud, fue construido en el siglo VII por el rey tibetano Songtsen Gampo y ampliado monumentalmente en el siglo XVII por el quinto Dalái Lama, Ngawang Lobsang Gyatso, hasta alcanzar sus actuales 13 pisos y más de 1.000 habitaciones. El palacio fue durante siglos el centro político, espiritual y administrativo del Tíbet, sede del gobierno teocrático de los Dalái Lamas y lugar de enterramiento de ocho de ellos en magníficos relicarios de oro y piedras preciosas. Tras la incorporación del Tíbet a la República Popular China en 1950 y el exilio del decimocuarto Dalái Lama en 1959, el palacio fue convertido en museo, aunque sigue siendo el símbolo más poderoso de la identidad tibetana.', '0637-01-01', '2024-12-19', false, 'STORY', 'ACTIVE', 4, 144);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (145, 'Los pilares de cuarzo que inspiraron Pandora', 'Las formaciones de arenisca de cuarzo de Zhangjiajie, que se elevan verticalmente hasta 200 metros sobre el fondo de los valles cubiertos de vegetación subtropical, fueron creadas por millones de años de erosión fluvial y eólica sobre antiguos lechos marinos del período Devónico. La zona fue habitada históricamente por el pueblo Tujia, cuya cultura y tradiciones milenarias están íntimamente ligadas a estos paisajes únicos, considerados sagrados en su cosmología. Zhangjiajie se convirtió en el primer parque forestal nacional de China en 1982, y su reconocimiento internacional creció enormemente cuando el director James Cameron se inspiró en sus pilares de piedra para crear los paisajes del planeta Pandora en la película Avatar (2009).', '0001-01-01', '2024-01-09', false, 'INFORMATION', 'ACTIVE', 1, 145);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (146, 'El gran palacio de la dinastía Joseon', 'El Palacio Gyeongbokgung, cuyo nombre significa "palacio de la felicidad radiante en todos los ángulos", fue construido en 1395 como residencia principal de los reyes de la dinastía Joseon, que gobernaría Corea durante más de cinco siglos hasta 1897. El palacio fue incendiado y destruido durante la invasión japonesa de 1592 liderada por Toyotomi Hideyoshi, permaneciendo en ruinas durante casi tres siglos hasta su reconstrucción en 1867 por orden del regente Heungseon Daewongun. Durante la ocupación japonesa de Korea (1910-1945), las autoridades coloniales demolieron deliberadamente muchos de sus edificios y construyeron el Gobierno General japonés frente a la puerta principal, en un acto simbólico de dominación cultural que fue revertido tras la independencia.', '1395-10-28', '2024-02-03', false, 'STORY', 'ACTIVE', 2, 146);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (147, 'El volcán sagrado del pueblo Tengger', 'El Monte Bromo, con sus 2.329 metros de altitud, es uno de los volcanes más activos de Java y el corazón espiritual del pueblo Tengger, una comunidad hindú que se considera descendiente de los refugiados del gran Imperio Majapahit que huyeron a las montañas tras la llegada del islam al siglo XV. Cada año, durante el festival Yadnya Kasada, los tenggereses realizan una peregrinación nocturna hasta el cráter del volcán para arrojar ofrendas de frutos, verduras, dinero y animales vivos a las fauces del volcán, en una ceremonia que lleva siglos realizándose sin interrupción. El nombre Bromo es la versión javanesa de Brahma, el dios hindú de la creación, lo que refleja la profunda sacralidad que esta comunidad atribuye al volcán.', '0001-01-01', '2024-03-15', false, 'INFORMATION', 'ACTIVE', 3, 147);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (148, 'El corazón histórico de Dubái', 'El barrio histórico de Al Fahidi, antiguamente conocido como Al Bastakiya, es el núcleo urbano original de Dubái, establecido a finales del siglo XIX por mercaderes persas provenientes de la región de Bastak que se instalaron a orillas del Creek atraídos por las políticas comerciales favorables del jeque Maktoum bin Hasher. Las características torres de viento (barjeel) que adornan los tejados de las casas de coral y barro son un ingenioso sistema de ventilación premoderno que capturaba las brisas del mar para enfriar los interiores de las viviendas en el sofocante calor del Golfo Pérsico. El barrio fue salvado de la demolición en los años 80 gracias a la intervención del jeque Mohammed bin Rashid Al Maktoum, quien ordenó su preservación como testimonio del pasado mercantil de la ciudad.', '1890-01-01', '2024-04-28', false, 'STORY', 'ACTIVE', 4, 148);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (149, 'La reina del desierto', 'Palmira, conocida en arameo como Tadmor, fue durante los siglos I y III d.C. una de las ciudades más ricas e importantes del mundo antiguo, gracias a su posición estratégica como oasis en la ruta de la seda que conectaba el Imperio Romano con Persia, India y China. La ciudad alcanzó su máximo esplendor bajo la reina Zenobia, quien en el año 270 d.C. se rebeló contra Roma, conquistó Egipto y gran parte de Asia Menor, y se proclamó emperatriz de un efímero Imperio de Palmira que duró apenas dos años antes de ser aplastado por el emperador Aureliano. En 2015, las fuerzas del Estado Islámico ocuparon Palmira y destruyeron sistemáticamente algunos de sus monumentos más valiosos, incluyendo el Templo de Bel y el Arco de Triunfo, en un ataque deliberado contra el patrimonio de la humanidad.', '0270-01-01', '2024-05-07', false, 'INFORMATION', 'ACTIVE', 1, 149);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (150, 'El último bastión de los zelotes', 'Masada, una meseta rocosa a 400 metros sobre el Mar Muerto, fue convertida por el rey Herodes el Grande entre el 37 y el 31 a.C. en una fortaleza de lujo con palacios, baños termales y enormes cisternas de agua, concebida como refugio personal en caso de revuelta. Tras la destrucción del Templo de Jerusalén en el año 70 d.C., un grupo de cerca de 960 zelotes judíos, los últimos resistentes de la Gran Revuelta Judía contra Roma, se refugió en Masada y resistió el asedio del ejército romano durante tres años. Según el relato del historiador Flavio Josefo, cuando los romanos finalmente lograron traspasar las murallas en el año 73 d.C., encontraron a la mayoría de los defensores muertos, pues habían preferido el suicidio colectivo a la esclavitud.', '0073-04-16', '2024-06-12', false, 'STORY', 'ACTIVE', 2, 150);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (151, 'Los templos más grandes de Roma', 'Baalbek, conocida en época romana como Heliopolis o "ciudad del sol", alberga el mayor conjunto de templos romanos jamás construido, incluyendo el Templo de Júpiter cuyas seis columnas corintias supervivientes, de 22 metros de altura, siguen siendo las columnas de granito más grandes del mundo antiguo. Los romanos construyeron sobre un santuario fenicio preexistente, aprovechando la sacralidad del lugar y las enormes plataformas de piedra que los ingenieros locales habían erigido siglos antes, incluyendo bloques megalíticos de hasta 800 toneladas cuyo traslado sigue siendo un misterio para los arqueólogos modernos. Tras la cristianización del Imperio Romano en el siglo IV, el templo fue transformado en basílica por orden del emperador Teodosio, y posteriormente los árabes construyeron una ciudadela fortificada reutilizando sus materiales.', '0060-01-01', '2024-07-04', false, 'INFORMATION', 'ACTIVE', 3, 151);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (152, 'La capital ceremonial del Imperio Persa', 'Persépolis fue fundada por el rey persa Darío I alrededor del año 518 a.C. como capital ceremonial del Imperio Aqueménida, el mayor imperio del mundo hasta entonces, que se extendía desde los Balcanes hasta el Indo y desde Egipto hasta Asia Central. Los frisos de la gran Escalinata de Apadana representan a delegaciones de 23 naciones del imperio portando tributos, convirtiéndose en el registro visual más detallado de los pueblos del mundo antiguo que se conoce. En el año 330 a.C., Alejandro Magno conquistó y saqueó Persépolis, y según las fuentes antiguas ordenó su incendio durante una fiesta, destruyendo irreparablemente uno de los conjuntos monumentales más importantes del mundo antiguo.', '0001-01-01', '2024-08-08', false, 'STORY', 'ACTIVE', 4, 152);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (153, 'La ciudad tres veces santa', 'Jerusalén es la única ciudad del mundo que es simultáneamente lugar sagrado para tres grandes religiones monoteístas: el judaísmo, el cristianismo y el islam, lo que la ha convertido en el centro de numerosos conflictos religiosos y militares a lo largo de más de tres milenios de historia documentada. La ciudad fue conquistada por el rey David alrededor del año 1000 a.C. y convertida en capital del reino de Israel, su hijo Salomón construyó el Primer Templo en el Monte Moria, y desde entonces la ciudad ha sido conquistada, destruida y reconstruida por babilonios, persas, griegos, romanos, cruzados, mamelucos y otomanos. Las murallas actuales de la Ciudad Vieja fueron construidas por el sultán otomano Solimán el Magnífico entre 1537 y 1541, enmarcando un espacio de apenas un kilómetro cuadrado que alberga algunos de los lugares más sagrados de la humanidad.', '0001-01-01', '2024-09-25', false, 'INFORMATION', 'ACTIVE', 1, 153);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (154, 'El templo hindú más alto del sudeste asiático', 'Prambanan es un complejo de templos hinduistas construido en el siglo IX por la dinastía Sanjaya del reino matarámico, dedicado a la Trimurti hinduista formada por Brahma el creador, Vishnu el preservador y Shiva el destructor, siendo el templo central de Shiva el más alto con sus 47 metros de altura. Según la leyenda javanesa, Prambanan fue construida en una sola noche por el genio Bandung Bondowoso para conquistar el amor de la princesa Rara Jonggrang, quien para evitar el matrimonio ordenó encender fogatas y hacer ruido de pisones para engañar al genio haciéndole creer que amanecía antes de tiempo. El conjunto fue abandonado y enterrado bajo las cenizas volcánicas alrededor del siglo X, y su redescubrimiento occidental se produjo en 1811 durante la breve administración colonial británica de Java.', '0850-01-01', '2024-10-16', false, 'STORY', 'ACTIVE', 2, 154);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (155, 'El gran buda de bronce de Nara', 'El Templo Todai-ji fue construido por orden del emperador Shomu entre 745 y 752 d.C. como cabeza del sistema de templos provinciales budistas que el estado japonés estableció para proteger al país mediante el poder espiritual del budismo, reflejo de la profunda influencia de la cultura continental china y coreana en el Japón del período Nara. El Gran Buda de bronce (Daibutsu) que alberga su Salón Principal es la mayor estatua de bronce del mundo, con 15 metros de altura y un peso de más de 500 toneladas, y su fundición en el siglo VIII requirió casi todo el bronce disponible en Japón en aquella época. El edificio actual del Salón Principal, aunque es la mayor estructura de madera del mundo, es solo dos tercios del tamaño original que fue destruido por guerras e incendios a lo largo de los siglos.', '0752-04-09', '2024-11-21', false, 'INFORMATION', 'ACTIVE', 3, 155);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (156, 'El techo de África', 'El Kilimanjaro, con sus 5.895 metros sobre el nivel del mar, es la montaña más alta de África y uno de los pocos volcanes del mundo que presenta glaciares tropicales en su cima, aunque los científicos estiman que estos glaciares podrían desaparecer completamente antes de 2040 debido al cambio climático. Para los pueblos Chagga que habitan sus laderas fértiles, el Kilimanjaro ha sido considerado sagrado durante siglos y fuente de vida gracias a las aguas que descienden de sus glaciares, alimentando la agricultura de la región. La primera ascensión documentada hasta la cumbre Uhuru fue realizada el 6 de octubre de 1889 por el geógrafo alemán Hans Meyer y el alpinista austriaco Ludwig Purtscheller, aunque guías locales Chagga como Lauwo los acompañaron en la hazaña.', '1889-10-06', '2024-12-02', false, 'STORY', 'ACTIVE', 4, 156);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (157, 'La gran migración de la vida salvaje', 'El Serengeti, cuyo nombre en lengua masai significa "llanura interminable", alberga la mayor migración terrestre de animales del planeta, en la que cada año más de 1,5 millones de ñus, acompañados de cebras y gacelas, recorren un circuito de 3.000 kilómetros siguiendo las lluvias en busca de pastos frescos. El pueblo masai habitó estas llanuras durante siglos como pastores seminómadas, coexistiendo con la fauna salvaje mediante un equilibrio que quedó alterado con la creación del Parque Nacional del Serengeti en 1951, que implicó el desalojo forzoso de las comunidades masai del área protegida. La primera expedición científica sistemática al Serengeti fue organizada en 1913 por el naturalista alemán Bernhard Grzimek y su hijo Michael, cuyo avión se estrelló en la misma región que estudiaban en 1959, siendo ambos enterrados en el cráter del Ngorongoro.', '0001-01-01', '2024-01-31', false, 'INFORMATION', 'ACTIVE', 1, 157);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (158, 'El humo que truena', 'Las Cataratas Victoria son llamadas Mosi-oa-Tunya, "el humo que truena", por los pueblos Kololo de la región, nombre que describe perfectamente la nube de vapor y el rugido ensordecedor que produce el salto de más de 100 metros de altura del río Zambeze sobre un ancho de 1.700 metros, convirtiéndolas en las cataratas más grandes del mundo por volumen de agua. El explorador escocés David Livingstone fue el primer europeo en contemplar las cataratas el 16 de noviembre de 1855, y las bautizó en honor a la reina Victoria de Gran Bretaña, aunque los pueblos locales las conocían y veneraban desde tiempo inmemorial. La frontera entre Zambia y Zimbabue atraviesa el desfiladero justo por la mitad de las cataratas, herencia de la época colonial cuando el territorio pertenecía a la Compañía Británica de África del Sur de Cecil Rhodes.', '1855-11-16', '2024-02-26', false, 'STORY', 'ACTIVE', 2, 158);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (159, 'La ciudad medieval más grande del mundo islámico', 'La medina de Fez al-Bali fue fundada en el año 789 por Idris I, el fundador de la primera dinastía árabe del Magreb, siendo considerada la ciudad más antigua de Marruecos y uno de los centros del saber islámico medieval más importantes del mundo, gracias a la Universidad Al-Karaouine, fundada en 859 y considerada la universidad en funcionamiento continuo más antigua del mundo. El laberíntico tejido urbano de la medina, con sus más de 9.000 callejuelas y 300.000 habitantes, se ha mantenido prácticamente sin cambios desde el período medieval, constituyendo el área urbana histórica de mayor tamaño del mundo en funcionamiento. Las tenerías de cuero de Chouara, donde los artesanos tiñen las pieles siguiendo métodos que datan del siglo XI usando palomina, salvado de trigo y azafrán, son uno de los lugares de trabajo artesanal más antiguos del mundo aún en activo.', '0789-01-01', '2024-03-31', false, 'INFORMATION', 'ACTIVE', 3, 159);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (160, 'Las dunas de arena más altas del Sahara marroquí', 'Erg Chebbi es uno de los dos grandes ergs de dunas de arena del Marruecos, con colinas que alcanzan los 150 metros de altura, formadas por el transporte eólico de arena a lo largo de miles de años en un proceso que continúa activamente en la actualidad. La región ha sido habitada y atravesada durante milenios por los tuaregs y otras tribus bereberes nómadas, que desarrollaron profundos conocimientos sobre la navegación del desierto y el aprovechamiento de los escasos recursos hídricos de este ambiente extremo. Las rutas de caravanas que cruzaban el Sahara transportando oro, sal, esclavos y marfil desde el África subsahariana hacia el norte durante los siglos VII al XV pasaban por esta zona, conectando civilizaciones a través de una de las barreras geográficas más hostiles del planeta.', '0001-01-01', '2024-04-10', false, 'STORY', 'ACTIVE', 4, 160);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (161, 'El cabo de las tormentas', 'El Cabo de Buena Esperanza fue avistado por primera vez por el navegante portugués Bartolomeu Dias en 1488, quien lo bautizó inicialmente como "Cabo das Tormentas" por las violentas tempestades que encontró al doblarlo, siendo el primer europeo en circunnavegar el extremo sur del continente africano. El rey João II de Portugal rebautizó el cabo como "Buena Esperanza" al comprender que el descubrimiento de esta ruta abría el camino hacia las codiciadas especias de India, objetivo estratégico que haría de Portugal la primera potencia colonial europea. Fue Vasco de Gama quien en 1497 completó la hazaña de navegar más allá del cabo y llegar a India, inaugurando la ruta marítima que durante más de tres siglos dominó el comercio entre Europa y Asia.', '1488-02-03', '2024-05-22', false, 'INFORMATION', 'ACTIVE', 1, 161);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (162, 'Las iglesias talladas en la roca', 'Lalibela debe su nombre al rey Gebre Mesqel Lalibela, que gobernó el Imperio etíope entre finales del siglo XII y principios del XIII y ordenó la construcción de once iglesias monolíticas talladas directamente en la roca volcánica roja, concibiendo la ciudad como una nueva Jerusalén para los peregrinos etíopes que no podían viajar a Tierra Santa tras la conquista musulmana. Según la tradición etíope, el rey Lalibela fue transportado al cielo por ángeles que le mostraron las iglesias que debía construir, y la labor fue ejecutada milagrosamente durante la noche por ángeles mientras los trabajadores humanos dormían, lo que explica la extraordinaria perfección de las tallas. La Iglesia de San Jorge (Bete Giyorgis), tallada en forma de cruz griega y decorada con cruces en relieve, es considerada la más perfecta de todas y sigue siendo un centro de peregrinación activo de la Iglesia Ortodoxa Etíope.', '1200-01-01', '2024-06-07', false, 'STORY', 'ACTIVE', 2, 162);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (163, 'El corazón palpitante de Marrakech', 'La plaza Jemaa el-Fna, cuyo nombre significa aproximadamente "asamblea de los muertos" en árabe, posiblemente en alusión a las ejecuciones públicas que allí se realizaban en la era medieval, es el epicentro de la vida social de Marrakech desde la fundación de la ciudad por la dinastía almorávide en el siglo XI. Durante siglos, la plaza ha sido el escenario de una tradición oral viva donde cuentacuentos (hlaiqia), músicos gnawa, encantadores de serpientes, acróbatas y herboristas congregan a locales y visitantes en un espectáculo que se renueva cada día al caer la tarde. En 2001, la UNESCO incluyó la plaza en su lista de Obras Maestras del Patrimonio Oral e Intangible de la Humanidad, reconociendo por primera vez a un espacio público vivo como bien cultural a preservar.', '1070-01-01', '2024-07-18', false, 'INFORMATION', 'ACTIVE', 3, 163);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (164, 'La ciudad que desafió a Roma', 'Cartago fue fundada, según la tradición, en el año 814 a.C. por colonos fenicios procedentes de Tiro, liderados por la reina Dido, y se convirtió en la principal potencia del Mediterráneo occidental durante siglos, controlando rutas comerciales desde España hasta Sicilia y compitiendo directamente con Roma por la hegemonía del mundo antiguo. Las tres Guerras Púnicas entre Roma y Cartago (264-146 a.C.) definieron el destino del Mediterráneo antiguo, siendo el general cartaginés Aníbal Barca quien protagonizó la segunda con su legendaria travesía de los Alpes con elefantes de guerra para invadir Italia. En el año 146 a.C., tras la Tercera Guerra Púnica, el Senado romano decretó la destrucción total de Cartago: la ciudad fue incendiada durante 17 días, sus ciudadanos esclavizados y el suelo sembrado simbólicamente con sal para que nada volviera a crecer.', '0001-01-01', '2024-08-20', false, 'STORY', 'ACTIVE', 4, 164);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (165, 'La necrópolis de los faraones', 'El Valle de los Reyes, situado en la orilla occidental del Nilo frente a la antigua Tebas, fue el cementerio real del Nuevo Imperio egipcio durante casi cinco siglos (1550-1070 a.C.), donde se construyeron más de 60 tumbas para faraones, reinas y altos dignatarios, todas ellas excavadas en la roca caliza y decoradas con textos religiosos destinados a guiar al difunto en el más allá. A pesar de los elaborados sistemas de protección y maldiciones inscritas en las paredes, prácticamente todas las tumbas fueron saqueadas en la antigüedad, con la notable excepción de la tumba de Tutankamón, descubierta prácticamente intacta por Howard Carter el 4 de noviembre de 1922 en lo que fue el mayor hallazgo arqueológico del siglo XX. Los artesanos que construyeron y decoraron las tumbas reales vivían en el poblado de Deir el-Medina, cuya extraordinaria conservación ha permitido conocer con detalle la vida cotidiana de los trabajadores del Estado egipcio hace 3.000 años.', '0001-01-01', '2024-09-09', false, 'INFORMATION', 'ACTIVE', 1, 165);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (166, 'El mayor ser vivo del planeta', 'La Gran Barrera de Coral es el mayor sistema de arrecifes coralinos del mundo, con más de 2.300 kilómetros de extensión y una superficie de 344.000 kilómetros cuadrados, siendo tan grande que puede verse desde el espacio y constituyendo el mayor organismo vivo del planeta, compuesto por billones de diminutos pólipos de coral. Los pueblos aborígenes australianos e isleños del Estrecho de Torres han mantenido una relación espiritual y material con los ecosistemas de la Gran Barrera durante más de 60.000 años, siendo la conexión humana continua más larga con este ecosistema. Los científicos advierten que el blanqueamiento masivo de corales causado por el calentamiento del océano, que ha afectado a más del 50% del arrecife desde 2016, representa una amenaza existencial para este ecosistema único, cuya desaparición tendría consecuencias devastadoras para la biodiversidad marina global.', '0001-01-01', '2024-10-30', false, 'STORY', 'ACTIVE', 2, 166);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (167, 'La roca sagrada del pueblo Anangu', 'Uluru, una monolítica formación arenisca de 348 metros de altura y 9,4 kilómetros de perímetro en el corazón del desierto australiano, es el lugar más sagrado del pueblo Anangu, para quienes constituye un nodo central del Tjukurpa, el sistema de conocimiento espiritual y ley que conecta a los seres humanos con el tiempo de los ancestros primordiales. Los primeros europeos en registrar la roca fueron el explorador William Gosse en 1873, quien la rebautizó como Ayers Rock en honor al primer ministro de Australia del Sur, aunque los Anangu nunca dejaron de llamarla por su nombre original. En 2019, después de décadas de peticiones de las comunidades aborígenes, las autoridades australianas cerraron definitivamente el acceso a la escalada de Uluru, reconociendo el daño espiritual que el turismo masivo había causado a un lugar de profundo significado sagrado.', '0001-01-01', '2024-11-06', false, 'INFORMATION', 'ACTIVE', 3, 167);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (168, 'El fiordo más famoso del mundo', 'Milford Sound, llamado Piopiotahi en lengua maorí en honor al piopio, un pájaro hoy extinto, es en realidad un fiordo y no un estuario, formado por el avance y retroceso de glaciares durante las últimas glaciaciones, que excavaron valles en forma de U que posteriormente fueron inundados por el mar. Para el pueblo Ngāi Tahu, el fiordo es un lugar de profundo significado espiritual y fue durante siglos un destino de las expediciones de los guerreros maorí en busca del pounamu (jade verde), la piedra más preciada de su cultura, que se encuentra en las montañas de esta región del sur de Nueva Zelanda. El explorador europeo que cartografió el fiordo con precisión fue el capitán John Lort Stokes en 1851, aunque el navegante galés John Grono había sido el primero en registrarlo en 1812, bautizándolo en honor a su pueblo natal de Milford Haven.', '0001-01-01', '2024-12-11', false, 'STORY', 'ACTIVE', 4, 168);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (169, 'La Comarca en el corazón de Nueva Zelanda', 'La granja Alexander en Matamata, en la región neozelandesa de Waikato, fue elegida en 1998 por el director Peter Jackson como localización para construir el poblado hobbit de La Comarca tras un reconocimiento aéreo del territorio, atraído por las suaves colinas verdes, el roble solitario en la cima y el tranquilo lago que conformaban un paisaje idéntico al descrito por J.R.R. Tolkien en El Señor de los Anillos. Las 37 puertas-agujero originales construidas para las películas de El Señor de los Anillos (2001-2003) fueron demolidas tras el rodaje, pero se reconstruyeron permanentemente con materiales duraderos para la trilogía de El Hobbit (2012-2014), convirtiendo el lugar en una atracción turística permanente. La transformación de la granja en destino turístico de fama mundial ha tenido un impacto económico enorme en la región de Waikato, generando miles de empleos y atrayendo a cientos de miles de peregrinos tolkienianos cada año.', '2001-12-19', '2024-01-20', false, 'INFORMATION', 'ACTIVE', 1, 169);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (170, 'La perla del Pacífico Sur', 'Bora Bora fue habitada por primera vez por polinesios procedentes de las islas de la Sociedad alrededor del siglo IV d.C., quienes la llamaron Pora Pora, "nacida primero" en su lengua, en alusión a la tradición de que fue una de las primeras islas creadas por el dios Taaroa. El primer europeo en avistar la isla fue el navegante neerlandés Jakob Roggeveen en 1722, aunque fue James Cook quien realizó los primeros mapas detallados durante sus tres expediciones al Pacífico en la segunda mitad del siglo XVIII. Durante la Segunda Guerra Mundial, Estados Unidos estableció una importante base de suministros en la isla a partir de 1942, construyendo el aeropuerto, carreteras y cañones defensivos que aún pueden verse, y cuya presencia introdujo cambios irreversibles en la economía y sociedad de la isla.', '0400-01-01', '2024-02-08', false, 'STORY', 'ACTIVE', 2, 170);
INSERT INTO post (id, title, content, date, posted_at, is_by_ia, category, status, author_id, location_id) VALUES (171, 'El primer Patrimonio Mundial de doble valor', 'El Parque Nacional Tongariro, que alberga tres volcanes activos en el corazón de la Isla Norte neozelandesa incluyendo el Ruapehu, el Ngauruhoe y el Tongariro, fue el cuarto parque nacional establecido en el mundo en 1887, gracias a la donación que el jefe maorí Te Heuheu Tūkino IV realizó al pueblo neozelandés para proteger estas montañas sagradas de la colonización. Para el pueblo Ngāti Tūwharetoa, los volcanes de Tongariro representan los antepasados que protegen a la tribu y constituyen el eje espiritual de su identidad cultural, siendo considerados ancestros literales y no meras formaciones geológicas. En 1993, Tongariro se convirtió en el primer lugar del mundo en recibir la designación de Patrimonio de la Humanidad por sus valores culturales indígenas además de sus valores naturales, reconociendo la cosmovisión maorí que ve en el paisaje natural un legado sagrado de los ancestros.', '1887-09-23', '2024-03-05', false, 'INFORMATION', 'ACTIVE', 3, 171);
